52	func (s *S3AccessLogUnmarshaler) UnmarshalAWSLogs(reader io.Reader) (plog.Logs, error) {
53		// Decode as a stream but flush all at once using flush options
54		streamUnmarshaler, err := s.NewLogsDecoder(reader, encoding.WithFlushItems(0), encoding.WithFlushBytes(0))
55		if err != nil {
56			return plog.Logs{}, err
57		}
58		logs, err := streamUnmarshaler.DecodeLogs()
59		if err != nil {
60			// we must check for EOF with direct comparison and avoid wrapped EOF that can come from stream itself
61			//nolint:errorlint
62			if err == io.EOF {
63				// EOF indicates no logs were found, return any logs that's available
64				return logs, nil
65			}
66	
67			return logs, err
68		}
69		return logs, nil
70	}
