74	// Supports offset-based streaming; offset tracks bytes processed
75	func (s *S3AccessLogUnmarshaler) NewLogsDecoder(reader io.Reader, options ...encoding.DecoderOption) (encoding.LogsDecoder, error) {
76		scannerHelper, err := xstreamencoding.NewScannerHelper(reader, options...)
77		if err != nil {
78			return nil, err
79		}
80	
81		decoderF := func() (plog.Logs, error) {
82			logs, resourceLogs, scopeLogs := s.createLogs()
83			resourceAttr := &resourceAttributes{}
84	
85			for {
86				log, flush, err := scannerHelper.ScanString()
87				if err != nil {
88					if !errors.Is(err, io.EOF) {
89						return plog.Logs{}, fmt.Errorf("error reading S3 access logs from stream:: %w", err)
90					}
91	
92					if log == "" {
93						break
94					}
95				}
96	
97				if err := handleLog(resourceAttr, scopeLogs, log); err != nil {
98					return plog.Logs{}, err
99				}
100	
101				if flush {
102					break
103				}
104			}
105	
106			s.setResourceAttributes(resourceAttr, resourceLogs)
107	
108			if scopeLogs.LogRecords().Len() == 0 {
