18	// ScannerHelper is a helper to scan new line delimited records from io.Reader and determine when to flush.
19	// It uses new line delimiters and bytes for batching.
20	// Not safe for concurrent use.
21	type ScannerHelper struct {
22		batchHelper *BatchHelper
23		bufReader   *bufio.Reader
24		offset      int64
25	}
26	
27	// NewScannerHelper creates a new ScannerHelper that reads from the provided io.Reader.
28	// It accepts optional encoding.DecoderOption to configure batch flushing behavior.
29	// If a bufio.Reader is provided, it will be used as-is. Otherwise, one will be derived with default buffer size.
30	func NewScannerHelper(reader io.Reader, opts ...encoding.DecoderOption) (*ScannerHelper, error) {
31		batchHelper := NewBatchHelper(opts...)
32	
33		var bufReader *bufio.Reader
34		if br, ok := reader.(*bufio.Reader); ok {
35			bufReader = br
36		} else {
37			bufReader = bufio.NewReader(reader)
38		}
39	
40		if batchHelper.options.Offset != 0 {
41			_, err := bufReader.Discard(int(batchHelper.options.Offset))
42			if err != nil {
43				return nil, fmt.Errorf("failed to discard offset %d: %w", batchHelper.options.Offset, err)
44			}
45		}
46	
47		return &ScannerHelper{
48			batchHelper: batchHelper,
49			bufReader:   bufReader,
50			offset:      batchHelper.options.Offset,
51		}, nil
52	}
