54	// ScanString scans the next line from the stream and returns it as a string. This excludes new line delimiter.
55	// flush indicates whether the batch should be flushed after processing this string.
56	// err is non-nil if an error occurred during scanning. If the end of the stream is reached, err will be io.EOF.
57	func (h *ScannerHelper) ScanString() (line string, flush bool, err error) {
58		internal, b, err := h.scanInternal()
59		return string(internal), b, err
60	}
61	
62	// ScanBytes scans the next line from the stream and returns it as a byte slice. This excludes new line delimiter.
63	// flush indicates whether the batch should be flushed after processing these bytes.
64	// err is non-nil if an error occurred during scanning. If the end of the stream is reached, err will be io.EOF.
65	func (h *ScannerHelper) ScanBytes() (bytes []byte, flush bool, err error) {
66		b, flush, err := h.scanInternal()
67		if b != nil {
68			cpy := make([]byte, len(b))
69			copy(cpy, b)
70			return cpy, flush, err
71		}
72		return nil, flush, err
73	}
