75	func (h *ScannerHelper) scanInternal() ([]byte, bool, error) {
76		var isEOF bool
77		b, err := h.bufReader.ReadBytes('\n')
78		if err != nil {
79			if err != io.EOF {
80				return nil, false, err
81			}
82			isEOF = true
83		}
84	
85		if len(b) == 0 && isEOF {
86			return nil, true, io.EOF
87		}
88	
89		h.offset += int64(len(b))
90		h.batchHelper.IncrementBytes(int64(len(b)))
91		h.batchHelper.IncrementItems(1)
92	
93		var flush bool
94		if h.batchHelper.ShouldFlush() {
95			h.batchHelper.Reset()
96			flush = true
97		}
98	
99		b = bytes.TrimSpace(b)
100	
101		if isEOF {
102			return b, flush, io.EOF
103		}
104	
105		return b, flush, nil
106	}
