134	// IncrementBytes adds n to the current byte count.
135	func (sh *BatchHelper) IncrementBytes(n int64) {
136		sh.currentBytes += n
137	}
138	
139	// IncrementItems adds n to the current item count.
140	func (sh *BatchHelper) IncrementItems(n int64) {
141		sh.currentItems += n
142	}
143	
144	// ShouldFlush returns true if the current counts exceed configured thresholds.
145	// Make sure to call Reset after flushing to start tracking the next batch.
146	func (sh *BatchHelper) ShouldFlush() bool {
147		if sh.options.FlushBytes > 0 && sh.currentBytes >= sh.options.FlushBytes {
148			return true
149		}
150		if sh.options.FlushItems > 0 && sh.currentItems >= sh.options.FlushItems {
151			return true
152		}
153		return false
154	}
155	
156	// Reset resets the current byte and item counts to zero.
157	// Should be called after flushing a batch to start tracking the next batch.
158	func (sh *BatchHelper) Reset() {
159		sh.currentBytes = 0
160		sh.currentItems = 0
161	}
